std::string image_base64(const std::string& bytes){static constexpr char alphabet[]="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";std::string out;out.reserve((bytes.size()+2)/3*4);for(std::size_t p=0;p<bytes.size();p+=3){unsigned a=static_cast<unsigned char>(bytes[p]),b=p+1<bytes.size()?static_cast<unsigned char>(bytes[p+1]):0,c=p+2<bytes.size()?static_cast<unsigned char>(bytes[p+2]):0;out+=alphabet[a>>2];out+=alphabet[((a&3)<<4)|(b>>4)];out+=p+1<bytes.size()?alphabet[((b&15)<<2)|(c>>6)]:'=';out+=p+2<bytes.size()?alphabet[c&63]:'=';}return out;}
std::string image_unbase64(const std::string& text,std::size_t limit){require(!text.empty()&&text.size()%4==0&&text.size()<=(limit+2)/3*4,"Invalid image base64 size");const auto digit=[](char c)->int {if(c>='A'&&c<='Z')return c-'A';if(c>='a'&&c<='z')return c-'a'+26;if(c>='0'&&c<='9')return c-'0'+52;if(c=='+')return 62;if(c=='/')return 63;return -1;};std::string out;for(std::size_t p=0;p<text.size();p+=4){const int a=digit(text[p]),b=digit(text[p+1]),c=text[p+2]=='='?0:digit(text[p+2]),d=text[p+3]=='='?0:digit(text[p+3]);const bool last=p+4==text.size(),pad2=text[p+2]=='=',pad1=text[p+3]=='=';require(a>=0&&b>=0&&c>=0&&d>=0&&(!pad2||pad1)&&(!(pad1||pad2)||last)&&(!pad2||!(b&15))&&(!pad1||pad2||!(c&3)),"Invalid image base64 encoding");out.push_back(static_cast<char>((a<<2)|(b>>4)));if(!pad2)out.push_back(static_cast<char>((b<<4)|(c>>2)));if(!pad1)out.push_back(static_cast<char>((c<<6)|d));}require(out.size()<=limit,"Image exceeds byte limit");return out;}
std::string encode_png(const RgbaImage& image){require(image.width&&image.height&&static_cast<std::uint64_t>(image.width)*image.height<=image_pixel_limit&&image.pixels.size()==static_cast<std::size_t>(image.width)*image.height*4,"Invalid native image size");std::string rows;rows.reserve((static_cast<std::size_t>(image.width)*4+1)*image.height);for(std::uint32_t y=0;y<image.height;++y){rows+='\0';rows.append(reinterpret_cast<const char*>(image.pixels.data()+static_cast<std::size_t>(y)*image.width*4),image.width*4);}std::string header;put32(header,image.width);put32(header,image.height);header.append("\x08\x06\0\0\0",5);std::string png("\x89PNG\r\n\x1a\n",8);chunk(png,"IHDR",header);chunk(png,"IDAT",deflate(rows));chunk(png,"IEND","");return png;}
